def init(self):
    """Initialise XBeach (only run once)"""
    logger.debug('Initializing...')
    if self.shouldinitialize:
        self._lib.init()
    self.shouldinitialize = False
def executestep(self):
    """Execute a timestep, stops before or on tnext"""
    self._lib.executestep()
def output(self):
    """Call XBeach output"""
    self._lib.outputext()
